// Extract the inbound WhatsApp message and resolve the connected business.
// Only ACTIVE, CONNECTED numbers are served (business_whatsapp filters).
const body = $input.first().json.body;
const change = body?.entry?.[0]?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

if (!message || message.type !== 'text') {
  return [];
}

const from = String(message.from || '');
const text = String(message.text?.body || '').trim();
if (!from || !text) return [];

const base = $env.N8N_SUPABASE_URL + '/rest/v1';
const headers = {
  apikey: $env.N8N_SUPABASE_SERVICE_KEY,
  Authorization: 'Bearer ' + $env.N8N_SUPABASE_SERVICE_KEY,
  Accept: 'application/json',
};

const phoneNumberId = String(value?.metadata?.phone_number_id || '');
let businessId = null;
if (phoneNumberId) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/business_whatsapp?phone_number_id=eq.${encodeURIComponent(phoneNumberId)}&is_active=eq.true&status=eq.connected&select=business_id,display_phone_number&limit=1`,
    headers,
    json: true,
  });
  businessId = Array.isArray(resp) && resp.length > 0 ? resp[0].business_id : null;
}

let cart = [];
let step = 'idle';
let lastConfirmedMessageId = null;
if (businessId) {
  const sessionResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/whatsapp_sessions?business_id=eq.${businessId}&chat_id=eq.${encodeURIComponent(from)}&select=state&limit=1`,
    headers,
    json: true,
  });
  const state = sessionResp?.[0]?.state;
  if (state && typeof state === 'object') {
    cart = Array.isArray(state.cart) ? state.cart : [];
    step = state.step || 'idle';
    lastConfirmedMessageId = state.lastConfirmedMessageId || null;
  }
}

const contactName = String(value?.contacts?.[0]?.profile?.name || '');

return [{
  json: {
    from,
    messageId: String(message.id || ''),
    text,
    contactName,
    phoneNumberId,
    displayPhoneNumber: String(value?.metadata?.display_phone_number || ''),
    businessId,
    found: Boolean(businessId),
    cart,
    step,
    lastConfirmedMessageId,
  },
}];

// Core bot logic: AI-assisted intent/order understanding (OpenRouter) with
// deterministic state transitions. AI understands; code decides and persists.
const c = $input.first().json;
const base = $env.N8N_SUPABASE_URL + '/rest/v1';
const headers = {
  apikey: $env.N8N_SUPABASE_SERVICE_KEY,
  Authorization: 'Bearer ' + $env.N8N_SUPABASE_SERVICE_KEY,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const money = (cents) => '$' + (cents / 100).toLocaleString('es-AR');
const cart = c.cart || [];

// ----- Idempotency: Meta may retry the same message; never reply twice -----
if (c.lastConfirmedMessageId === c.messageId && c.lastConfirmedMessageId) {
  return [{ json: { ...c, reply: 'Tu pedido ya fue enviado ✅' } }];
}

// ----- Deterministic control intents (never delegated to the model) -----
const isYes = /^(si|sip|ok|okey|dale|confirm|confirmar|listo)$/i.test(c.text.trim());
const isNo = /^(no|nop|cancel|cancelar|borrar|vaciar|reset)$/i.test(c.text.trim());
const controlIntent =
  (c.step === 'confirming' || cart.length) && isYes ? 'confirm_order'
  : (c.step === 'confirming' || cart.length) && isNo ? 'cancel_cart'
  : null;

// ----- Keyword parser (fallback + intent validation) -----
function parseByKeywords() {
  const text = c.text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const has = (...patterns) => patterns.some((p) => text.includes(p));
  let intent;
  if (has('hola', 'buenas', 'ayuda', 'help', 'empezar', 'que se puede hacer', 'qué se puede hacer')) intent = 'help';
  else if (has('menú', 'menu', 'carta', 'que tienen', 'qué tienen', 'que venden', 'qué venden', 'listado')) intent = 'menu';
  else if (has('horario', 'abierto', 'cerrado', 'abren', 'cierran', 'hasta que hora')) intent = 'hours';
  else if (has('cancelar', 'borrar', 'vaciar', 'reset')) intent = 'cancel_cart';
  else intent = 'add_item';
  let items = [];
  if (intent === 'add_item' && text) {
    let qty = 1;
    let term = text;
    const m = text.match(/^(\d+)\s+(.+)/);
    if (m) { qty = Math.min(99, Math.max(1, parseInt(m[1], 10))); term = m[2]; }
    else if (/^un[ao]?\s/.test(text)) { term = text.replace(/^un[ao]?\s/, ''); }
    items = [{ name: term, quantity: qty }];
  }
  return { intent, items };
}

// ----- AI parser via OpenRouter (openrouter/free) -----
async function parseByAI() {
  if (!$env.N8N_OPENROUTER_API_KEY) return null;
  const prods = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/products?business_id=eq.' + c.businessId + '&available=eq.true&select=name,price_cents&order=sort_order.asc',
    headers,
    json: true,
  });
  const menu = (prods || []).map((p) => `- ${p.name} (${money(p.price_cents)})`).join('\n') || '(carta vacía)';
  const sys = [
    'Sos el bot de un local de comida. Interpretás mensajes de clientes por WhatsApp.',
    'Respondé SOLO con JSON válido, sin texto extra. Format:',
    '{"intent": "menu|hours|help|add_item|cancel_cart", "items": [{"name":"<nombre del producto tal cual en la carta>", "quantity": <numero entero 1-99>}], "reply": "<respuesta corta y cordial al texto libre que no sea un pedido>"}',
    'Reglas:',
    `- La carta disponible es:\n${menu}`,
    '- "intent=add_item": el cliente pide productos. Indicá los items con nombre EXACTO de la carta y su cantidad. Si parte no existe, poné solo los que coincidan.',
    '- "intent=menu": pide la carta. "intent=hours": horarios. "intent=help": saludo/ayuda.',
    '- "reply" es obligatorio y se usa para texto libre (no para pedidos).',
    '- Respetá la cantidad; default 1.',
  ].join('\n');
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      Authorization: 'Bearer ' + $env.N8N_OPENROUTER_API_KEY,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'http://localhost:3000',
      'X-OpenRouter-Title': 'BolivarPide',
    },
    body: {
      model: 'openrouter/free',
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: sys },
        { role: 'user', content: c.text },
      ],
    },
    json: true,
  });
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) return null;
  const parsed = JSON.parse(content);
  const valid = ['help', 'menu', 'hours', 'add_item', 'cancel_cart'].includes(parsed?.intent);
  if (!valid) return null;
  const items = Array.isArray(parsed.items) ? parsed.items.map((i) => ({
    name: String(i?.name || '').trim(),
    quantity: Math.min(99, Math.max(1, parseInt(i?.quantity, 10) || 1)),
  })).filter((i) => i.name) : [];
  return { intent: parsed.intent, items, reply: parsed.reply || null };
}

// ----- Pick parser: try AI, fall back to keywords -----
let parsed = Object.assign({}, parseByKeywords(), { source: 'keywords' });
if (controlIntent) {
  parsed = { intent: controlIntent, items: [], source: 'control' };
} else {
  try {
    const ai = await parseByAI();
    if (ai && (ai.intent !== 'add_item' || ai.items.length > 0)) {
      parsed = Object.assign({}, ai, { source: 'ai' });
    }
  } catch (e) {
    console.log('AI ERRO:', (e && e.message) ? e.message : String(e));
    console.log('AI STACK:', (e && e.stack) ? e.stack.substring(0, 300) : '');
  }
}

const intent = parsed.intent;
const aiReply = parsed.reply || null;

// ----- MENÚ -----
if (intent === 'menu') {
  const prods = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/products?business_id=eq.' + c.businessId + '&available=eq.true&select=name,price_cents&order=sort_order.asc',
    headers, json: true,
  });
  if (!prods.length) {
    return [{ json: { ...c, reply: 'Todavía no cargamos la carta 📝. Volvé pronto.' } }];
  }
  const lines = prods.map((p) => '• ' + p.name + ' — ' + money(p.price_cents));
  return [{ json: { ...c, reply: '🪧 Menú:\n' + lines.join('\n') + '\n\nEscribí la cantidad y el plato, ej: "2 muzza".' } }];
}

// ----- HORARIOS (reales desde business_hours) -----
if (intent === 'hours') {
  const days = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/business_hours?business_id=eq.' + c.businessId + '&select=weekday,open_time,close_time,closed&order=weekday.asc',
    headers, json: true,
  });
  if (!rows.length) {
    return [{ json: { ...c, reply: 'Aún no configuramos los horarios de este local 🕐.' } }];
  }
  const fmtTime = (t) => (t ? String(t).slice(0, 5) : '--:--');
  const lines = rows.map((r) => {
    const name = days[r.weekday] || ('Día ' + r.weekday);
    return r.closed ? `• ${name}: Cerrado` : `• ${name}: ${fmtTime(r.open_time)} a ${fmtTime(r.close_time)}`;
  });
  return [{ json: { ...c, reply: '🕐 Horarios de atención:\n' + lines.join('\n') } }];
}

// ----- CANCELAR / VACIAR -----
if (intent === 'cancel_cart') {
  await this.helpers.httpRequest({
    method: 'POST', url: base + '/rpc/whatsapp_session_reset', headers,
    body: { p_business_id: c.businessId, p_chat_id: c.from, p_step: 'idle', p_cart: [] },
    json: true,
  });
  return [{ json: { ...c, reply: 'Cancelamos el carrito 🗑️. Escribí "menú" para volver a empezar.', cart: [], step: 'idle' } }];
}

// ----- CONFIRMAR PEDIDO -----
if (intent === 'confirm_order') {
  if (!cart.length) {
    return [{ json: { ...c, reply: 'Tu carrito está vacío 🛒. Escribí ej: "2 muzza".' } }];
  }
  const payload = {
    businessId: c.businessId,
    waChatId: c.from,
    customerName: c.contactName || undefined,
    customerPhone: c.from,
    notes: 'Pedido por WhatsApp',
    items: cart.map((i) => ({ productId: i.productId, name: i.name, quantity: i.quantity, unitPriceCents: i.unitPriceCents })),
  };
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.N8N_APP_URL + '/api/webhooks/whatsapp',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'x-whatsapp-secret': $env.N8N_WHATSAPP_WEBHOOK_SECRET },
    body: payload,
    returnFullResponse: true,
    json: true,
  });
  const ok = resp.statusCode < 300 && resp.body && resp.body.success === true;
  if (ok) {
    await this.helpers.httpRequest({
      method: 'POST', url: base + '/rpc/whatsapp_session_reset', headers,
      body: { p_business_id: c.businessId, p_chat_id: c.from, p_step: 'idle', p_cart: [], p_last_confirmed_message_id: c.messageId },
      json: true,
    });
    return [{ json: { ...c, reply: '✅ ¡Pedido enviado al local! Número: *' + resp.body.orderId + '*', cart: [], step: 'idle' } }];
  }
  return [{ json: { ...c, reply: '😕 Hubo un problema al registrar tu pedido. Escribí *cancelar* y probá de nuevo.' } }];
}

// ----- AYUDA / texto libre -----
if (intent === 'help') {
  const reply = aiReply || (() => {
    let cartTxt = '';
    if (cart.length) {
      const sum = cart.reduce((acc, i) => acc + i.quantity * i.unitPriceCents, 0);
      cartTxt = '\n\n📋 Tu carrito:\n' + cart.map((i) => `${i.quantity}x ${i.name} — ${money(i.quantity * i.unitPriceCents)}`).join('\n') + '\nTotal: ' + money(sum) + '\n\nEscribí *confirmar* para enviarlo.';
    }
    const lines = [
      `¡Hola${c.contactName ? ' ' + c.contactName : ''}! 👋`,
      'Soy el bot de este local.',
      '• *menú* — ver la carta',
      '• *horario* — horarios de atención',
      '• Ej: *"2 muzza"* — armar el pedido',
      '• *confirmar* — enviar el pedido',
      '• *cancelar* — vaciar el carrito',
    ];
    return lines.join('\n') + cartTxt;
  })();
  return [{ json: { ...c, reply } }];
}

// ----- AGREGAR ITEM(S) (atómicos vía RPC; items resueltos contra catálogo) -----
const items = parsed.items || [];
const resolvedLines = [];
const missing = [];
for (const it of items) {
  const prods = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/products?business_id=eq.' + c.businessId + '&available=eq.true&name=ilike.*' + encodeURIComponent(it.name) + '*&select=id,name,price_cents&order=sort_order.asc&limit=5',
    headers, json: true,
  });
  if (!prods.length) {
    missing.push(it.name);
    continue;
  }
  resolvedLines.push({ product: prods[0], quantity: it.quantity });
}
if (missing.length) {
  return [{ json: { ...c, reply: 'No encontramos *"' + missing.join('", "') + '"* en la carta 😕. Probá con "menú".' } }];
}
if (!resolvedLines.length) {
  return [{ json: { ...c, reply: 'Escribí qué querés pedir, ej: *"2 muzza"*.' } }];
}

let state = { cart, step: 'confirming' };
for (const line of resolvedLines) {
  const sessionResp = await this.helpers.httpRequest({
    method: 'POST', url: base + '/rpc/whatsapp_session_add_item', headers,
    body: {
      p_business_id: c.businessId,
      p_chat_id: c.from,
      p_product: { productId: line.product.id, name: line.product.name, quantity: line.quantity, unitPriceCents: line.product.price_cents },
    },
    json: true,
  });
  if (sessionResp && typeof sessionResp === 'object') state = sessionResp;
}
const newCart = Array.isArray(state.cart) ? state.cart : cart;
const sum = newCart.reduce((acc, i) => acc + i.quantity * i.unitPriceCents, 0);
const list = newCart.map((i) => `${i.quantity}x ${i.name} — ${money(i.quantity * i.unitPriceCents)}`).join('\n');

return [{
  json: {
    ...c,
    cart: newCart,
    step: 'confirming',
    reply: `Agregamos ${resolvedLines.map((l) => `*${l.quantity}x ${l.product.name}*`).join(', ')} ✅\n\n📋 Carrito:\n${list}\n*Total: ${money(sum)}*\n\n¿Confirmás? Escribí *confirmar* o *cancelar*.`,
  },
}];
